    for (int nl = 0; nl < outer_loop_count; nl++) {
        // Vectorizable update of a[i] - process 8 elements at a time
        int i = 0;
        for (; i + 7 < 256; i += 8) {
            a[i] += b[i] * c[i];
            a[i+1] += b[i+1] * c[i+1];
            a[i+2] += b[i+2] * c[i+2];
            a[i+3] += b[i+3] * c[i+3];
            a[i+4] += b[i+4] * c[i+4];
            a[i+5] += b[i+5] * c[i+5];
            a[i+6] += b[i+6] * c[i+6];
            a[i+7] += b[i+7] * c[i+7];
        }
        // Scalar cleanup tail
        for (; i < 256; i++) {
            a[i] += b[i] * c[i];
        }

        // Process each column independently - vectorize across i where possible
        for (int i = 0; i < 256; i++) {
